#include<bits/stdc++.h>
using namespace std;
using ll=long long;

vector<ll>solve(ll n,vector<ll>f)
{
  vector<ll>vec(n);
  for(int i=1;i+1<n;i++)
  {
    if((f[i+1]+f[i-1]-2*f[i])%2!=0)return {};
    vec[i]=(f[i+1]+f[i-1]-2*f[i])/2;
    if(abs(vec[i])>1000)return {};
  }
  auto g=[&](ll j)
  {
    ll w=f[j];
    for(int i=1;i+1<n;i++)
    {
      w-=vec[i]*abs(i-j);
    }
    return w;
  };
  ll g1=g(0),gn=g(n-1);
  if(gn%(n-1)!=0)return {};
  if(g1%(n-1)!=0)return {};
  vec[0]=gn/(n-1);
  vec[n-1]=g1/(n-1);
  if(abs(vec[0])>1000||abs(vec[n-1])>1000)return {};
  return vec;
}

int main()
{
  int t;cin>>t;
  while(t--)
  {
    ll n;cin>>n;
    vector<ll>f(n);
    for(ll&i:f)cin>>i;
    auto a=solve(n,f);
    assert(a.size()==n);
    for(int i=0;i<n;i++)cout<<a[i]<<" \n"[i+1==n];
  }
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;
const ll md=1000000007;

int main()
{
  int t;cin>>t;
  while(t--)
  {
    ll n;cin>>n;
    vector<ll>L(n),R(n);
    for(int i=0;i<n;i++)
    {
      cin>>L[i]>>R[i];
      L[i]--;R[i]--;
    }
    vector<ll>dp(n);
    auto dfs1=[&](auto dfs1,int x)->ll
    {
      if(L[x]==-1)return dp[x]=1;
      else return dp[x]=(dfs1(dfs1,L[x])+dfs1(dfs1,R[x])+3)%md;
    };
    dfs1(dfs1,0);
    auto dfs2=[&](auto dfs2,int x)->void
    {
      if(L[x]==-1)return;
      else
      {
        dp[L[x]]=(dp[L[x]]+dp[x])%md;
        dp[R[x]]=(dp[R[x]]+dp[x])%md;
        dfs2(dfs2,L[x]);
        dfs2(dfs2,R[x]);
      }
    };
    dfs2(dfs2,0);
    for(int i=0;i<n;i++)cout<<dp[i]<<" \n"[i+1==n];
  }
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;

struct Quad{ll a,b,c;}; // ax^2+bx+c

// f(x) < g(x) for all x
bool comp(Quad f,Quad g)
{
  if(f.a>g.a)return false;
  else if(f.a==g.a)return f.b==g.b&&f.c<g.c;
  else
  {
    Quad Q{g.a-f.a,g.b-f.b,g.c-f.c};
    return Q.b*Q.b-4*Q.a*Q.c<0;
  }
}

int main()
{
  cin.tie(0)->sync_with_stdio(0);
  int t;cin>>t;
  while(t--)
  {
    int n;cin>>n;
    vector<Quad>vec(n);
    for(Quad&Q:vec)cin>>Q.a>>Q.b>>Q.c;
    vector<vector<int>>adj1(n),adj2(n);
    vector<int>id1(n),id2(n),dp1(n,1),dp2(n,1);
    for(int i=0;i<n;i++)
    {
      for(int j=0;j<n;j++)
      {
        if(comp(vec[i],vec[j]))
        {
          adj1[i].push_back(j);
          id1[j]++;
          adj2[j].push_back(i);
          id2[i]++;
        }
      }
    }
    queue<int>Q;
    for(int i=0;i<n;i++)if(id1[i]==0)Q.push(i);
    while(!Q.empty())
    {
      int a=Q.front();Q.pop();
      for(int i:adj1[a])
      {
        id1[i]--;dp1[i]=max(dp1[i],dp1[a]+1);
        if(id1[i]==0)Q.push(i);
      }
    }
    for(int i=0;i<n;i++)if(id2[i]==0)Q.push(i);
    while(!Q.empty())
    {
      int a=Q.front();Q.pop();
      for(int i:adj2[a])
      {
        id2[i]--;dp2[i]=max(dp2[i],dp2[a]+1);
        if(id2[i]==0)Q.push(i);
      }
    }
    for(int i=0;i<n;i++)cout<<dp1[i]+dp2[i]-1<<" \n"[i+1==n];
  }
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;

int main()
{
  ll t;cin>>t;
  while(t--)
  {
    ll n,q;cin>>n>>q;
    vector<ll>L(n),R(n),P(n,-1);
    for(int i=0;i<n;i++)P[i]=i;
    for(int i=0;i<n;i++)
    {
      cin>>L[i]>>R[i];
      L[i]--;R[i]--;
      if(L[i]!=-1)
      {
        P[L[i]]=i;
        P[R[i]]=i;
      }
    }
    vector<ll>dp(n);
    vector<array<int,20>>lift(n);
    auto dfs1=[&](auto dfs1,int x)->ll
    {
      if(L[x]==-1)return dp[x]=1;
      else return dp[x]=(dfs1(dfs1,L[x])+dfs1(dfs1,R[x])+3);
    };
    dfs1(dfs1,0);
    vector<ll>euler,tin(n);
    auto dfs2=[&](auto dfs2,int x)->void
    {
      tin[x]=euler.size();
      lift[x][0]=P[x];
      for(int j=1;j<20;j++)
      {
        lift[x][j]=lift[lift[x][j-1]][j-1];
      }
      if(L[x]==-1)
      {
        euler.push_back(x);
        return;
      }
      else
      {
        dp[L[x]]=(dp[L[x]]+dp[x]);
        dp[R[x]]=(dp[R[x]]+dp[x]);
        euler.push_back(x);
        dfs2(dfs2,L[x]);
        euler.push_back(x);
        dfs2(dfs2,R[x]);
        euler.push_back(x);
      }
    };
    dfs2(dfs2,0);
    while(q--)
    {
      ll v,k;cin>>v>>k;
      v--;
      ll w=v;
      for(int j=19;j>=0;j--)
      {
        if(dp[v]-dp[lift[w][j]]<=k)w=lift[w][j];
      }
      k-=dp[v]-dp[w];
      cout<<euler[tin[w]+k]+1<<" \n"[q==0];
    }
  }
}

